namespace ghidra.app.util.exporter;





using ghidra.app.util;
using ghidra.app.util.xml;
using ghidra.app.util.xml;
using ghidra.framework.model;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;

/**
 * An implementation of exporter that creates
 * an XML representation of the program.
 */
public class XmlExporter : ProgramExporter {
	private XmlProgramOptions options = new XmlProgramOptions();

	/**
	 * Constructs a new XML exporter.
	 */
	public XmlExporter() : base("XML", "xml", new HelpLocation("ExporterPlugin", "xml"))
    {
	}

	/* @Override */
	public List<Option> getOptions(DomainObjectService domainObjectService) {
		if (options == null) {
			options = new XmlProgramOptions();
		}
		return options.getOptions(false);
	}

	/* @Override */
	public void setOptions(List<Option> options)
    {
		this.options.setOptions(options);
	}

	/* @Override */
	public bool export(File file, DomainObject domainObj, AddressSetView addrSet, TaskMonitor monitor)
    {

		log.clear();

		Program program;
		try {
			program = getProgram(domainObj);
		}
		catch (ClassCastException e) {
			log.appendMsg("Unsupported type: " + domainObj.GetType().getName());
			return false;
		}

		if (addrSet == null) {
			addrSet = program.getMemory();
		}

		ProgramXmlMgr mgr = new ProgramXmlMgr(file);

		try {
			log = mgr.write(program, addrSet, monitor, options);
		}
		catch (CancelledException e) {
			throw new ExporterException("User cancelled XML export.");
		}

		options = null;

		return true;
	}
}
